package org.marketreview.nativeapp;
import android.content.*;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.view.View;
import android.widget.*;
import android.text.*;
import org.json.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
public final class DataSourceStatusScreen extends LinearLayout {
 public interface Host{void openNative(String route,JSONObject exactTarget)throws Exception;default void exportEvidence(byte[] safeEvidence)throws Exception{throw new Exception("未连接导出入口");}default boolean supportsExport(){return false;}}
 private final Host host;private JSONObject current;private final Set<String> allowed=new HashSet<>();private final Map<String,Spinner> fields=new LinkedHashMap<>();private final Map<String,List<String>> codes=new LinkedHashMap<>();
 private final TextView message,pager,detail,raw;private final EditText search;private final LinearLayout filtersPanel,rowsPanel,detailPanel,rawPanel;private final ScrollView scroll;private final Button open,previous,next,mode;private String selected="",lastFilters="";private int page,viewMode;private boolean updating,active=true,closed,dark;
 public DataSourceStatusScreen(Context context,Host host){super(context);this.host=host;setTag("dataSourceStatusPage");setOrientation(VERTICAL);setSaveEnabled(false);setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);try{current=DataSourceStatusModel.empty();}catch(Exception e){current=new JSONObject();}
  message=new TextView(context);message.setText("本机持有证据；授权与稳定实时能力未知");message.setMaxLines(1);message.setEllipsize(android.text.TextUtils.TruncateAt.END);addView(message,new LayoutParams(-1,-2));
  LinearLayout tools=new LinearLayout(context);addView(tools,new LayoutParams(-1,dp(48)));Button filterButton=small("筛选/导出","dataSourceFilters"),listButton=small("列表","dataSourceList");mode=small("完整状态","dataSourceRawButton");open=small("返回功能","dataSourceOpen");for(Button button:new Button[]{filterButton,listButton,mode,open})tools.addView(button,new LayoutParams(0,-1,1));
  scroll=new ScrollView(context);scroll.setTag("dataSourceScroll");addView(scroll,new LayoutParams(-1,0,1));LinearLayout content=new LinearLayout(context);content.setOrientation(VERTICAL);scroll.addView(content);filtersPanel=new LinearLayout(context);filtersPanel.setOrientation(VERTICAL);content.addView(filtersPanel,new LayoutParams(-1,-2));filtersPanel.setVisibility(GONE);
  String[] keys={"provider","product","granularity","acquisition"},labels={"提供方","产品","粒度","取得状态"};for(int n=0;n<keys.length;n++){TextView label=new TextView(context);label.setText(labels[n]);filtersPanel.addView(label);Spinner field=new Spinner(context);field.setTag("dataSource"+keys[n]);fields.put(keys[n],field);codes.put(keys[n],new ArrayList<>(Collections.singletonList("*")));filtersPanel.addView(field,new LayoutParams(-1,dp(48)));field.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){filterChanged();}public void onNothingSelected(AdapterView<?> p){}});}
  search=new EditText(context);search.setTag("dataSourceSearch");search.setSingleLine(true);search.setSaveEnabled(false);search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});search.setHint("查提供方 / 产品 / 完整标的身份");filtersPanel.addView(search,new LayoutParams(-1,dp(48)));Button export=small("导出当前筛选的非敏感证据","dataSourceExport");filtersPanel.addView(export,new LayoutParams(-1,dp(48)));
  rowsPanel=new LinearLayout(context);rowsPanel.setTag("dataSourceRows");rowsPanel.setOrientation(VERTICAL);content.addView(rowsPanel,new LayoutParams(-1,-2));detailPanel=new LinearLayout(context);detailPanel.setOrientation(VERTICAL);content.addView(detailPanel,new LayoutParams(-1,-2));detail=new TextView(context);detail.setTag("dataSourceDetail");detail.setTextIsSelectable(true);detailPanel.addView(detail);rawPanel=new LinearLayout(context);rawPanel.setOrientation(VERTICAL);content.addView(rawPanel,new LayoutParams(-1,-2));raw=new TextView(context);raw.setTag("dataSourceRaw");raw.setTextIsSelectable(true);rawPanel.addView(raw);
  LinearLayout footer=new LinearLayout(context);footer.setTag("dataSourcePager");content.addView(footer,new LayoutParams(-1,dp(48)));previous=small("上一页","dataSourcePrevious");next=small("下一页","dataSourceNext");pager=new TextView(context);pager.setGravity(17);footer.addView(previous,new LayoutParams(0,-1,1));footer.addView(pager,new LayoutParams(0,-1,2));footer.addView(next,new LayoutParams(0,-1,1));
  filterButton.setOnClickListener(v->{if(usable())filtersPanel.setVisibility(filtersPanel.getVisibility()==VISIBLE?GONE:VISIBLE);});listButton.setOnClickListener(v->{if(usable()){viewMode=0;renderMode();}});mode.setOnClickListener(v->{if(usable()){viewMode=viewMode==2?1:2;renderMode();}});previous.setOnClickListener(v->{if(usable()&&page>0){--page;render();}});next.setOnClickListener(v->{if(usable()){++page;render();}});open.setOnClickListener(v->{if(!usable()||host==null)return;try{JSONObject record=selectedRecord();if(record!=null&&DataSourceStatusModel.canOpen(record,allowed))host.openNative(record.getString("route"),DataSourceStatusModel.navigation(record));}catch(Exception e){fail();}});
  export.setOnClickListener(v->{if(!usable())return;try{byte[] bytes=exportEvidence();if(host!=null&&host.supportsExport())host.exportEvidence(bytes);else{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getContext().getSystemService(Context.CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("本机来源白名单证据",new String(bytes,StandardCharsets.UTF_8)));message.setText("已复制筛选证据；未请求任何数据源");}}catch(Exception e){fail();}});
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){filterChanged();}public void afterTextChanged(Editable e){}});try{options();}catch(Exception e){fail();}render();setDarkTheme(false);
 }
 public void addFilterAccessory(View view){filtersPanel.addView(view);}
 private boolean usable(){return active&&!closed;}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private Button small(String text,String tag){Button b=new Button(getContext());b.setText(text);b.setTag(tag);b.setTextSize(12);b.setMinHeight(dp(48));b.setPadding(dp(3),0,dp(3),0);return b;}
 private JSONObject filters()throws Exception{JSONObject f=new JSONObject();for(String key:fields.keySet()){int index=fields.get(key).getSelectedItemPosition();List<String> list=codes.get(key);f.put(key,index>=0&&index<list.size()?list.get(index):"*");}return f.put("search",search.getText().toString());}
 private void filterChanged(){if(updating)return;try{String signature=filters().toString();if(signature.equals(lastFilters))return;page=0;selected="";viewMode=0;render();}catch(Exception e){fail();}}
 private void options()throws Exception{JSONObject prior=filters();updating=true;try{JSONArray records=current.getJSONArray("records");for(String key:fields.keySet()){TreeSet<String> values=new TreeSet<>();for(int n=0;n<records.length();n++)values.add(records.getJSONObject(n).getString(key));List<String> ids=new ArrayList<>();ids.add("*");ids.addAll(values);codes.put(key,ids);List<String> labels=new ArrayList<>();for(String value:ids)labels.add(value.equals("*")?"全部":key.equals("product")?DataSourceStatusModel.productName(value):DataSourceStatusModel.stateName(value));ArrayAdapter<String> adapter=new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_item,labels){public View getView(int p,View v,android.view.ViewGroup g){View x=super.getView(p,v,g);paint(x);return x;}public View getDropDownView(int p,View v,android.view.ViewGroup g){View x=super.getDropDownView(p,v,g);paint(x);x.setBackgroundColor(background());x.setMinimumHeight(dp(48));return x;}};adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);fields.get(key).setAdapter(adapter);int position=ids.indexOf(prior.optString(key,"*"));fields.get(key).setSelection(position<0?0:position);}}finally{updating=false;}}
 private JSONObject selectedRecord()throws Exception{JSONArray records=current.getJSONArray("records");for(int n=0;n<records.length();n++)if(records.getJSONObject(n).getString("key").equals(selected))return records.getJSONObject(n);return null;}
 private void render(){try{JSONObject f=filters();lastFilters=f.toString();JSONArray visible=DataSourceStatusModel.rows(current,f);page=Math.max(0,Math.min(page,Math.max(0,(visible.length()-1)/24)));rowsPanel.removeAllViews();boolean found=false;for(int n=page*24;n<visible.length()&&n<(page+1)*24;n++){JSONObject record=visible.getJSONObject(n);String key=record.getString("key");if(key.equals(selected))found=true;Button row=small(DataSourceStatusModel.title(record)+"\n取得："+DataSourceStatusModel.stateName(record.getString("acquisition"))+"；缓存："+DataSourceStatusModel.stateName(record.getString("cache")),"dataSourceRow:"+key);row.setMinHeight(dp(72));row.setSingleLine(false);rowsPanel.addView(row,new LayoutParams(-1,-2));row.setOnClickListener(v->{if(!usable())return;selected=key;viewMode=1;showSelected();});}if(!found)selected=visible.length()>page*24?visible.getJSONObject(page*24).getString("key"):"";if(visible.length()==0){TextView empty=new TextView(getContext());empty.setText("没有匹配的本机证据。未注入不等于来源不可用；全局能力仍未知。");rowsPanel.addView(empty);}pager.setText((page+1)+"/"+Math.max(1,(visible.length()+23)/24)+" · "+visible.length()+" 条");previous.setEnabled(page>0);next.setEnabled((page+1)*24<visible.length());showSelected();applyColors(this);}catch(Exception e){fail();}}
 private void showSelected(){try{JSONObject record=selectedRecord();if(record==null){detail.setText("没有已选择的本机证据");raw.setText("");open.setEnabled(false);}else{detail.setText(DataSourceStatusModel.description(record));raw.setText(record.toString(2));open.setEnabled(host!=null&&DataSourceStatusModel.canOpen(record,allowed));}renderMode();}catch(Exception e){fail();}}
 private void renderMode(){findViewWithTag("dataSourcePager").setVisibility(viewMode==0?VISIBLE:GONE);rowsPanel.setVisibility(viewMode==0?VISIBLE:GONE);detailPanel.setVisibility(viewMode==1?VISIBLE:GONE);rawPanel.setVisibility(viewMode==2?VISIBLE:GONE);scroll.scrollTo(0,0);}
 public void setSnapshot(JSONObject input){if(closed)return;try{JSONObject safe=DataSourceStatusModel.snapshot(input);current=safe;options();render();message.setText("主页面本机证据 · 注入时间："+(current.isNull("generatedAt")?"未知":current.getString("generatedAt"))+"；不证明授权或稳定实时");}catch(Exception e){fail();}}
 public void setAllowedRoutes(Collection<String> routes){allowed.clear();allowed.addAll(routes);showSelected();}
 public byte[] exportEvidence()throws Exception{return DataSourceStatusModel.exportEvidence(current,filters());}
 public JSONObject saveState(){try{JSONObject f=filters();if(java.util.regex.Pattern.compile("(sk-|bearer|api[_-]?key|password|authorization|token[=:])",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(f.optString("search")).find())f.put("search","");return new JSONObject().put("schema","native-data-source-status-ui/v1").put("filters",f).put("page",page).put("selected",selected).put("viewMode",viewMode);}catch(Exception e){return new JSONObject();}}
 public void restoreState(JSONObject state){if(!state.optString("schema").equals("native-data-source-status-ui/v1"))return;updating=true;try{JSONObject f=state.getJSONObject("filters");for(String key:fields.keySet()){int p=codes.get(key).indexOf(f.optString(key,"*"));fields.get(key).setSelection(p<0?0:p);}search.setText(f.optString("search","").substring(0,Math.min(120,f.optString("search","").length())));page=Math.max(0,Math.min(41,state.optInt("page")));String key=state.optString("selected","");selected=key.matches("[a-f0-9]{64}")?key:"";viewMode=Math.max(0,Math.min(2,state.optInt("viewMode")));}catch(Exception e){fail();}finally{updating=false;}render();}
 public void setActive(boolean value){active=value;}
 public void close(){closed=true;active=false;}
 public void setHostError(String ignored){fail();}
 private void fail(){message.setText("来源证据更新或导出失败；保留上一份通过检查的本机记录");}
 private int background(){return dark?Color.rgb(17,26,40):Color.rgb(245,248,252);}
 private ColorStateList colors(){return new ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{dark?Color.rgb(126,145,165):Color.rgb(100,116,139),dark?Color.rgb(235,241,249):Color.rgb(25,41,62)});}
 private void paint(View view){if(view instanceof TextView)((TextView)view).setTextColor(colors());}
 private void applyColors(View view){paint(view);if(view instanceof Spinner||view instanceof EditText)view.setBackgroundTintList(colors());if(view instanceof Button)view.setBackgroundTintList(ColorStateList.valueOf(dark?Color.rgb(39,55,77):Color.rgb(220,231,245)));if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int n=0;n<group.getChildCount();n++)applyColors(group.getChildAt(n));}}
 public void setDarkTheme(boolean value){dark=value;setBackgroundColor(background());applyColors(this);for(Spinner field:fields.values())if(field.getAdapter() instanceof ArrayAdapter)((ArrayAdapter<?>)field.getAdapter()).notifyDataSetChanged();}
}
